mapper.select:
SELECT user_id
FROM like_blog
WHERE blog_id = #{blogId}

SELECT user_id
FROM like_comment
WHERE comment_id = #{commentId}

mapper.insert:
INSERT IGNORE INTO like_blog (
    blog_id,
    user_id,
    create_time
) VALUES (
    #{blogId},
    #{userId},
    #{createTime}
)

mapper.delete:
DELETE FROM like_blog
WHERE blog_id = #{blogId}
  AND user_id = #{userId}

mapper.update:
UPDATE blog
SET like_count = (
    SELECT COUNT(*)
    FROM like_blog
    WHERE blog_id = #{blogId}
)
WHERE id = #{blogId}

mapper.insert:
INSERT IGNORE INTO like_comment (
    comment_id,
    user_id,
    create_time
) VALUES (
    #{commentId},
    #{userId},
    #{createTime}
)

mapper.delete:
DELETE FROM like_comment
WHERE comment_id = #{commentId}
  AND user_id = #{userId}

mapper.update:
UPDATE `comment`
SET like_count = (
    SELECT COUNT(*)
    FROM like_comment
    WHERE comment_id = #{commentId}
)
WHERE id = #{commentId}
